import{_ as t,o as r,c as a,a4 as o}from"./chunks/framework.BoUsC9QI.js";const f=JSON.parse('{"title":"브라우저 지원","description":"Neba는 Chrome과 Edge 111, Firefox 113, Safari 16.4 이상을 데스크톱과 모바일에서 모두 지원합니다. 네 브라우저 모두 2023년 3월에서 5월 사이에 나온 버전입니다. 이보다 오래된 브라우저는 지원하지 않습니다. color-mix()가 없으면 색이…","frontmatter":{"title":"브라우저 지원"},"headers":[],"relativePath":"ko/browser-support.md","filePath":"ko/browser-support.md","lastUpdated":1789441934000}'),d={name:"ko/browser-support.md"};function i(l,e,n,s,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="브라우저-지원" tabindex="-1">브라우저 지원 <a class="header-anchor" href="#브라우저-지원" aria-label="Permalink to &quot;브라우저 지원&quot;">​</a></h1><p>Neba는 Chrome과 Edge 111, Firefox 113, Safari 16.4 이상을 데스크톱과 모바일에서 모두 지원합니다. 네 브라우저 모두 2023년 3월에서 5월 사이에 나온 버전입니다. 이보다 오래된 브라우저는 지원하지 않습니다. <code>color-mix()</code>가 없으면 색이 대부분 그려지지 않고, 더 오래된 브라우저에서는 컴포넌트가 아예 동작하지 않습니다.</p><h2 id="최소-버전" tabindex="-1">최소 버전 <a class="header-anchor" href="#최소-버전" aria-label="Permalink to &quot;최소 버전&quot;">​</a></h2><table tabindex="0"><thead><tr><th>브라우저</th><th>최소 버전</th><th>출시</th></tr></thead><tbody><tr><td>Chrome, Android용 Chrome</td><td>111</td><td>2023년 3월</td></tr><tr><td>Edge</td><td>111</td><td>2023년 3월</td></tr><tr><td>Firefox, Android용 Firefox</td><td>113</td><td>2023년 5월</td></tr><tr><td>macOS, iOS, iPadOS의 Safari</td><td>16.4</td><td>2023년 3월</td></tr></tbody></table><ul><li>Opera, Samsung Internet 같은 다른 Chromium 기반 브라우저는 Chromium 111로 만든 릴리스부터 지원합니다.</li><li>iOS와 iPadOS에서 시스템 WebKit 엔진을 쓰는 브라우저는 Safari 행을 따르므로, 기준은 기기의 OS 버전입니다. iOS 15나 iPadOS 15보다 높게 업데이트할 수 없는 iPhone과 iPad는 지원 범위 밖입니다.</li><li>Firefox ESR은 115부터 모든 릴리스가 지원 범위 안에 있습니다.</li></ul><p>테스트는 Chromium, Firefox, WebKit의 현재 릴리스에서 돌리므로, 최소 버전을 브라우저에서 직접 테스트하지는 않습니다. 이 값은 다음 섹션의 기능과 Neba가 의존하는 패키지가 선언한 지원 범위에서 끌어냈고, 변경이 있을 때마다 CI가 stylesheet와 소스에서 쓰는 기능을 <a href="https://github.com/mdn/browser-compat-data" target="_blank" rel="noreferrer">MDN 호환성 데이터</a>와 대조합니다.</p><p>Neba가 그려지지 않는 브라우저를 위해 빌드가 transpile하는 일이 없도록 build target도 같은 범위로 맞추세요. <a href="https://browsersl.ist" target="_blank" rel="noreferrer">Browserslist</a> query로는 다음과 같습니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chrome &gt;= 111, edge &gt;= 111, firefox &gt;= 113, safari &gt;= 16.4, ios_saf &gt;= 16.4</span></span></code></pre></div><h2 id="최소-버전을-정하는-요소" tabindex="-1">최소 버전을 정하는 요소 <a class="header-anchor" href="#최소-버전을-정하는-요소" aria-label="Permalink to &quot;최소 버전을 정하는 요소&quot;">​</a></h2><table tabindex="0"><thead><tr><th>요구사항</th><th>Chrome, Edge</th><th>Firefox</th><th>Safari</th><th>여기에 기대는 것</th></tr></thead><tbody><tr><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Values/color_value/color-mix" target="_blank" rel="noreferrer"><code>color-mix()</code></a></td><td>111</td><td>113</td><td>16.2</td><td>파생 색 토큰 전부: 채움, hover와 press 상태, 틴트, 선, focus ring</td></tr><tr><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Values/color_value/oklch" target="_blank" rel="noreferrer"><code>oklch()</code></a></td><td>111</td><td>113</td><td>15.4</td><td>파생 토큰을 섞는 재료인 팔레트</td></tr><tr><td><a href="https://base-ui.com/react/overview/about" target="_blank" rel="noreferrer">Base UI</a> 1.x</td><td>111</td><td>113</td><td>16.4</td><td>인터랙티브 컴포넌트의 동작과 접근성</td></tr><tr><td><a href="https://tailwindcss.com/docs/compatibility" target="_blank" rel="noreferrer">Tailwind CSS</a> v4</td><td>111</td><td>128</td><td>16.4</td><td><code>neba/styles.css</code>에 컴파일해 넣은 utility class</td></tr></tbody></table><p>브라우저마다 그 열에서 가장 높은 숫자가 최소 버전이며, 예외가 하나 있습니다. Tailwind CSS는 <code>@property</code> 때문에 Firefox 128을 적어 두었지만, v4.1부터 fallback을 함께 내보내므로 Firefox 113~127에서도 같은 utility가 그려집니다. <code>neba/tailwind.css</code>를 직접 운영하는 Tailwind 빌드에 import한다면, 이 fallback이 빠지지 않도록 Tailwind CSS v4.1 이상을 쓰세요.</p><h3 id="더-낮출-수-없는-이유" tabindex="-1">더 낮출 수 없는 이유 <a class="header-anchor" href="#더-낮출-수-없는-이유" aria-label="Permalink to &quot;더 낮출 수 없는 이유&quot;">​</a></h3><p>한계는 <code>color-mix()</code>입니다. 색 계열 하나는 토큰 다섯 개이고, 나머지 색조는 모두 브라우저가 그 다섯을 섞어 만듭니다. 프로젝트가 토큰 하나만 덮어써도 모든 상태가 따라 바뀌는 것도 이 구조 때문입니다. <code>color-mix()</code>가 없는 브라우저는 비슷한 색으로 대신 그리지 않습니다. 토큰은 정의된 채로 남지만, 그 토큰을 <code>var()</code>로 읽는 속성은 computed-value 시점에 무효가 되어 <code>unset</code>처럼 동작합니다. 그래서 채움형 Button에 채움이 없고, hover나 press에도 색이 바뀌지 않습니다. 색을 빌드 시점에 미리 계산해 두면 그려지기는 하지만, 프로젝트가 덮어쓴 토큰은 모두 무시됩니다.</p><p>Base UI도 같은 범위를 선언합니다. Base UI는 마지막 메이저 버전을 낼 때 Baseline Widely Available로 표시된 기능을 모두 구현한 브라우저를 지원하고, <a href="https://github.com/mui/base-ui/blob/master/.browserslistrc" target="_blank" rel="noreferrer">Browserslist 파일</a>에 그 범위를 Chrome과 Edge 111, Firefox 113, Safari 16.4로 적어 두었습니다. 최소 버전을 더 낮추면 인터랙티브 컴포넌트가 자신의 primitive가 지원하지 않는 브라우저에서 돌게 됩니다.</p><p>transpile이나 polyfill을 써도 이 한계는 그대로입니다. 한계를 정하는 것은 JavaScript가 아닙니다. Neba와 Base UI의 코드가 지원 여부를 먼저 확인하지 않고 쓰는 기능은 <code>inert</code> attribute까지 포함해 모두 Chrome 102, Firefox 112, Safari 16에 들어 있습니다. 이 기준은 transpiler와 polyfill로 낮출 수 있지만, 브라우저에 <code>color-mix()</code>를 더할 방법은 없습니다.</p><h2 id="지원-범위-안에서-달라지는-점" tabindex="-1">지원 범위 안에서 달라지는 점 <a class="header-anchor" href="#지원-범위-안에서-달라지는-점" aria-label="Permalink to &quot;지원 범위 안에서 달라지는 점&quot;">​</a></h2><p>범위 안의 모든 브라우저에서 모든 컴포넌트가 그려지고 동작합니다. 다만 몇 가지 세부 표현은 더 새로운 기능을 쓰고, 그 기능이 없는 브라우저에서는 그 표현만 빠집니다.</p><table tabindex="0"><thead><tr><th>세부 표현</th><th>필요한 기능</th><th>범위 안의 이전 브라우저에서</th></tr></thead><tbody><tr><td><a href="./components/inputs/text-field">TextField</a>, <a href="./components/inputs/select">Select</a>, <a href="./components/inputs/combobox">Combobox</a>, <a href="./components/inputs/number-field">NumberField</a>, 날짜와 시간 picker, <a href="./components/inputs/rating">Rating</a>, 선택할 수 있는 <a href="./components/display/data-table">DataTable</a>의 2px focus ring</td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Selectors/:has" target="_blank" rel="noreferrer"><code>:has()</code></a>: Firefox 121</td><td>필드는 ring 없이 테두리나 채움으로 focus를 보여 주고, DataTable은 활성 행으로 보여 줍니다. Rating은 ring을 그대로 그리지만, 키보드로 옮긴 별뿐 아니라 클릭한 별에도 그립니다</td></tr><tr><td><a href="./components/inputs/checkbox">Checkbox</a>, <a href="./components/inputs/radio-group">RadioGroup</a>, <a href="./components/inputs/switch">Switch</a>, <a href="./components/feedback/alert">Alert</a>처럼 label이 붙은 행에서 label 옆에 놓인 상자나 아이콘</td><td><code>lh</code> 단위: Firefox 120</td><td>label 첫 줄의 가운데가 아니라 위쪽에 맞춰집니다</td></tr><tr><td><a href="./components/transitions/animate-split">AnimateSplit</a>, <a href="./components/transitions/animate-typing">AnimateTyping</a>, <a href="./components/transitions/animate-scramble">AnimateScramble</a>이 텍스트를 글자와 단어로 나누는 방식</td><td><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Intl/Segmenter" target="_blank" rel="noreferrer"><code>Intl.Segmenter</code></a>: Firefox 125</td><td>code point와 공백을 기준으로 나눕니다. code point 여러 개로 이루어진 이모지는 조각으로 나뉘어 나타나고, 띄어쓰기 없이 쓰는 언어의 문장은 한 단어로 취급됩니다</td></tr><tr><td><a href="./components/transitions/animate-lighting">AnimateLighting</a>의 움직이는 빛</td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/At-rules/@property" target="_blank" rel="noreferrer"><code>@property</code></a>: Firefox 128</td><td>빛이 한 자리에 머뭅니다</td></tr><tr><td><a href="./components/inputs/calendar">Calendar</a>와 날짜 picker에서 한 주가 시작하는 요일</td><td><a href="https://developer.mozilla.org/docs/Web/JavaScript/Reference/Global_Objects/Intl/Locale/getWeekInfo" target="_blank" rel="noreferrer"><code>Intl.Locale</code>의 주 정보</a>: Firefox 153</td><td><code>weekStartsOn</code>을 지정하지 않으면 일요일에 시작합니다</td></tr><tr><td>RTL 레이아웃에서 <a href="./components/layout/scroll-area">ScrollArea</a>와 <a href="./components/surfaces/tabs">Tabs</a>의 가장자리 fade</td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Selectors/:dir" target="_blank" rel="noreferrer"><code>:dir()</code></a>: Chrome과 Edge 120</td><td>왼쪽과 오른쪽 fade가 서로 바뀌지 않습니다</td></tr><tr><td><a href="./components/transitions/animate-fade">AnimateFade</a> 같은 Animate 컴포넌트의 <code>timeline=&quot;view&quot;</code></td><td><a href="https://developer.mozilla.org/docs/Web/CSS/Reference/Properties/animation-timeline" target="_blank" rel="noreferrer"><code>animation-timeline</code></a>: Chrome과 Edge 115, Safari 26, Firefox는 아직 미지원</td><td>scroll을 따라가지 않고 mount될 때 한 번 재생됩니다</td></tr></tbody></table>',18)])])}const m=t(d,[["render",i]]);export{f as __pageData,m as default};
